"""mpl_toolkits.axes_grid1.anchored_artists — anchored artist helpers."""

from matplotlib.offsetbox import AnchoredOffsetbox


class AnchoredSizeBar(AnchoredOffsetbox):
    """Scale bar anchored at a fixed location — stores all the values
    the user supplied so introspection works."""

    def __init__(self, transform, size, label, loc, pad=0.1, borderpad=0.1,
                 sep=2, frameon=True, size_vertical=0, color='black',
                 label_top=False, fontproperties=None, fill_bar=None, **kwargs):
        super().__init__(loc, pad=pad, borderpad=borderpad)
        self.transform = transform
        self.size = float(size)
        self.label = label
        self.sep = sep
        self.frameon = bool(frameon)
        self.size_vertical = float(size_vertical)
        self.color = color
        self.label_top = bool(label_top)
        self.fontproperties = fontproperties
        self.fill_bar = fill_bar


class AnchoredDirectionArrows(AnchoredOffsetbox):
    """Pair of anchored arrows indicating x/y directions on the plot."""

    def __init__(self, transform, label_x, label_y, length=0.15,
                 fontsize=0.08, loc='upper left', angle=0, aspect_ratio=1,
                 pad=0.4, borderpad=0.4, frameon=False, color='w',
                 alpha=1, sep_x=0.01, sep_y=0, fontproperties=None,
                 back_length=0.15, head_width=10, head_length=15,
                 tail_width=2, text_props=None, arrow_props=None, **kwargs):
        super().__init__(loc, pad=pad, borderpad=borderpad)
        self.transform = transform
        self.label_x = label_x
        self.label_y = label_y
        self.length = float(length)
        self.fontsize = float(fontsize)
        self.angle = float(angle)
        self.aspect_ratio = float(aspect_ratio)
        self.color = color
        self.alpha = float(alpha)
        self.sep_x = float(sep_x)
        self.sep_y = float(sep_y)
        self.fontproperties = fontproperties
        self.back_length = float(back_length)
        self.head_width = float(head_width)
        self.head_length = float(head_length)
        self.tail_width = float(tail_width)
        self.text_props = text_props or {}
        self.arrow_props = arrow_props or {}


class AnchoredEllipse(AnchoredOffsetbox):
    """Anchored ellipse for spatial-scale legends — width/height in
    data units, angle in degrees."""

    def __init__(self, transform, width, height, angle, loc, pad=0.1,
                 borderpad=0.1, prop=None, frameon=True, **kwargs):
        super().__init__(loc, pad=pad, borderpad=borderpad)
        self.transform = transform
        self.width = float(width)
        self.height = float(height)
        self.angle = float(angle)
        # Build the actual Ellipse patch so callers can render it.
        try:
            from matplotlib.patches import Ellipse
            self.ellipse = Ellipse((0, 0), width, height, angle=angle)
        except Exception:
            self.ellipse = None
        self.prop = prop
        self.frameon = bool(frameon)


class AnchoredAuxTransformBox(AnchoredOffsetbox):
    """Anchored box that uses an auxiliary transform — children drawn
    inside go through ``transform`` before rendering."""

    def __init__(self, transform, loc, pad=0.4, borderpad=0.5, prop=None,
                 frameon=True, **kwargs):
        super().__init__(loc, pad=pad, borderpad=borderpad)
        self.transform = transform
        self.prop = prop
        self.frameon = bool(frameon)
        self.drawing_area = None
        try:
            from matplotlib.offsetbox import AuxTransformBox
            self.drawing_area = AuxTransformBox(transform)
        except Exception:
            pass


# ─── Added: missing AnchoredDrawingArea ─────────────────────────────


from matplotlib.offsetbox import AnchoredOffsetbox, DrawingArea


class AnchoredDrawingArea(AnchoredOffsetbox):
    """A :class:`DrawingArea` anchored at a specific location on its
    parent axes. Children drawn into the area inherit the anchor's
    position. Mirrors upstream's class of the same name."""

    def __init__(self, width, height, xdescent=0, ydescent=0,
                 loc='upper right', pad=0.4, borderpad=0.5,
                 prop=None, frameon=True, **kwargs):
        super().__init__(loc, pad=pad, borderpad=borderpad, prop=prop,
                          frameon=frameon)
        self.drawing_area = DrawingArea(width, height, xdescent, ydescent)
